select left(stem,140) s from questions q join subject_groups g on g.id=q.subject_group_id where g.code='medical-science' and q.question_type<>'mcq' and (stem ilike '%fuse%' or stem ilike '%blood group%' or stem ilike '%balanced diet%' or stem ilike '%tetanus%' or stem ilike '%skeletal%' or stem ilike '%vitamin%' or stem ilike '%resistance%' or stem ilike '%stretched%' or stem ilike '%amalgam%' or stem ilike '%diphyodont%' or stem ilike '%EEG%' or stem ilike '%gram%' or stem ilike '%TB%' or stem ilike '%refractive%' or stem ilike '%telemedicine%' or stem ilike '%zoonotic%' or stem ilike '%rabies%' or stem ilike '%isometric%' or stem ilike '%digestion%');
